UPDATE code_sessions SET worker_lease_expires_at = #{expiresAt}, worker_last_heartbeat_at = NOW(),
    last_worker_activity_at = NOW(), connection_status = 'connected', updated_at = NOW()
WHERE organization_uuid = #{scope.OrganizationUUID} AND workspace_uuid = #{scope.WorkspaceUUID}
  AND uuid = #{scope.CodeSessionUUID} AND current_worker_epoch = #{scope.Epoch}
  AND status = 'active' AND deleted_at IS NULL
